pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft) public {
        vm.assume(baseToken != nft);
        uint128 virtualBaseTokenReserves = 100;
        uint128 virtualNftReserves = 100;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;
        c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties);
        assertEq(c.nft(), nft);
    }
}
